INSERT INTO `scenarios` (`id`, `name`, `description`, `sim_hours`, `start_hour`, `fleet`, `weather`, `policy`, `demand`, `baseline_run_id`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'Baseline — typical weekday', 'The city as it runs today: current fleet, dry weather, no interventions. Every other scenario is read against this one.', 24.00, 0.00, '{\"bike\": 30, \"ebike\": 45, \"scooter\": 90}', '{\"tempC\": 28, \"precipitationMm\": 0}', '{\"closedZones\": [], \"bikeLaneZones\": [], \"demandMultiplier\": 1, \"rebalanceEnabled\": false, \"rebalanceIntervalMin\": 60, \"rebalanceVanCapacity\": 8}', NULL, 1, 2, '2026-08-17 05:33:50.289', '2026-08-17 05:34:17.182', NULL),
(2, 'Protected bike lanes — city centre', 'Segregated infrastructure across the four central zones. Tests the safety case: does protected infrastructure cut the incident rate enough to justify it?', 24.00, 0.00, '{\"bike\": 30, \"ebike\": 45, \"scooter\": 90}', '{\"tempC\": 28, \"precipitationMm\": 0}', '{\"closedZones\": [], \"bikeLaneZones\": [\"3\", \"1\", \"2\", \"6\"], \"demandMultiplier\": 1, \"rebalanceEnabled\": false, \"rebalanceIntervalMin\": 60, \"rebalanceVanCapacity\": 8}', NULL, 2, 2, '2026-08-17 05:33:50.290', '2026-08-17 05:34:17.329', NULL),
(3, 'Overnight rebalancing', 'Vans redistribute idle vehicles every 45 minutes. Tests whether moving existing stock beats buying more of it — and what the empty kilometres cost.', 24.00, 0.00, '{\"bike\": 30, \"ebike\": 45, \"scooter\": 90}', '{\"tempC\": 28, \"precipitationMm\": 0}', '{\"closedZones\": [], \"bikeLaneZones\": [], \"demandMultiplier\": 1, \"rebalanceEnabled\": true, \"rebalanceIntervalMin\": 45, \"rebalanceVanCapacity\": 10}', NULL, 3, 2, '2026-08-17 05:33:50.291', '2026-08-17 05:34:17.344', NULL),
(4, 'Monsoon day', 'Heavy rain across the city. Tests fleet planning against the weather that actually suppresses ridership in Belagavi for weeks at a time.', 24.00, 0.00, '{\"bike\": 30, \"ebike\": 45, \"scooter\": 90}', '{\"tempC\": 23, \"precipitationMm\": 12}', '{\"closedZones\": [], \"bikeLaneZones\": [], \"demandMultiplier\": 1, \"rebalanceEnabled\": false, \"rebalanceIntervalMin\": 60, \"rebalanceVanCapacity\": 8}', NULL, 4, 2, '2026-08-17 05:33:50.292', '2026-08-17 05:34:17.380', NULL);
